/**
 * The WebUI must branch on what the server records: canonical
 * Stream.Protocol values, with HTTP/2 expressed as `protocol: "http"` plus
 * `http_version: "h2" | "h2c"`. Fixtures are real `query` responses and the
 * query handler's own filter enums, generated by
 * internal/mcp/webui_http_fixture_test.go.
 */

import { describe, expect, it } from "vitest";
import h1Text from "../../pages/FlowDetail/__fixtures__/h1-flow.response.json?raw";
import h2Text from "../../pages/FlowDetail/__fixtures__/h2-flow.response.json?raw";
import h2cText from "../../pages/FlowDetail/__fixtures__/h2c-flow.response.json?raw";
import flowsText from "../../pages/Flows/__fixtures__/flows-all-protocols.response.json?raw";
import enumsText from "./__fixtures__/query-filter-enums.json?raw";
import { isHttp2, protocolVariant } from "./dispatch.js";
import {
  HTTP_VERSION_FILTER_VALUES,
  PROTOCOL_BREAKDOWN,
  PROTOCOL_FILTER_VALUES,
  SCHEME_FILTER_VALUES,
} from "./protocols.js";
import type { FlowDetailResult, FlowsResult } from "./types.js";

const h1 = JSON.parse(h1Text) as FlowDetailResult;
const h2 = JSON.parse(h2Text) as FlowDetailResult;
const h2c = JSON.parse(h2cText) as FlowDetailResult;
const flows = JSON.parse(flowsText) as FlowsResult;
const enums = JSON.parse(enumsText) as {
  protocol: string[];
  http_version: string[];
  scheme: string[];
};

const recordedProtocols = new Set(flows.flows.map((f) => f.protocol));

describe("isHttp2", () => {
  it("is true for recorded h2 and h2c flows", () => {
    expect(isHttp2(h2)).toBe(true);
    expect(isHttp2(h2c)).toBe(true);
  });

  it("is false for a recorded HTTP/1.1 flow", () => {
    expect(isHttp2(h1)).toBe(false);
  });

  it("is true for legacy HTTP/2 protocol spellings without http_version", () => {
    // Old DBs / JSONL imports may hold display spellings in Stream.Protocol.
    expect(isHttp2({ protocol: "HTTP/2" })).toBe(true);
    expect(isHttp2({ protocol: "HTTP/2", http_version: "" })).toBe(true);
    expect(isHttp2({ protocol: "h2" })).toBe(true);
    expect(isHttp2({ protocol: "H2", http_version: "" })).toBe(true);
  });

  it("is false for a canonical http row without an h2 http_version", () => {
    expect(isHttp2({ protocol: "http", http_version: "" })).toBe(false);
    expect(isHttp2({ protocol: "http" })).toBe(false);
    expect(isHttp2({ protocol: "HTTP/1.x", http_version: "" })).toBe(false);
  });

  it("is false for non-HTTP protocols and missing input", () => {
    expect(isHttp2({ protocol: "grpc", http_version: "h2" })).toBe(false);
    expect(isHttp2({ protocol: "ws" })).toBe(false);
    expect(isHttp2(null)).toBe(false);
    expect(isHttp2(undefined)).toBe(false);
  });
});

describe("protocol filter values", () => {
  it("equal the set of protocols the recorder produces", () => {
    expect(new Set(PROTOCOL_FILTER_VALUES)).toEqual(recordedProtocols);
  });

  it("equal the server's accepted filter.protocol enum", () => {
    expect([...PROTOCOL_FILTER_VALUES].sort()).toEqual([...enums.protocol].sort());
  });

  it("http_version values are accepted by the server and cover h2 / h2c", () => {
    expect(HTTP_VERSION_FILTER_VALUES).toEqual(expect.arrayContaining(["h2", "h2c"]));
    for (const v of HTTP_VERSION_FILTER_VALUES) {
      expect(enums.http_version).toContain(v);
    }
  });

  it("scheme values are accepted by the server", () => {
    expect(SCHEME_FILTER_VALUES.length).toBeGreaterThan(0);
    for (const s of SCHEME_FILTER_VALUES) {
      expect(enums.scheme).toContain(s);
    }
  });
});

describe("Dashboard protocol breakdown", () => {
  it("has one row per recorded protocol", () => {
    const protocolOnly = PROTOCOL_BREAKDOWN.filter((b) => b.filter.http_version == null);
    expect(new Set(protocolOnly.map((b) => b.filter.protocol))).toEqual(recordedProtocols);
  });

  it("adds h2 and h2c rows as protocol=http + http_version", () => {
    const versions = PROTOCOL_BREAKDOWN.filter((b) => b.filter.http_version != null);
    expect(versions.map((b) => b.filter)).toEqual([
      { protocol: "http", http_version: "h2" },
      { protocol: "http", http_version: "h2c" },
    ]);
  });

  it("only sends filter values the server accepts", () => {
    for (const b of PROTOCOL_BREAKDOWN) {
      expect(enums.protocol).toContain(b.filter.protocol);
      if (b.filter.http_version != null) {
        expect(enums.http_version).toContain(b.filter.http_version);
      }
    }
  });
});

describe("protocolVariant", () => {
  it("colours each recorded protocol family", () => {
    const variants = Object.fromEntries(
      [...recordedProtocols].map((p) => [p, protocolVariant(p)]),
    );
    expect(variants).toEqual({
      http: "default",
      ws: "info",
      sse: "info",
      grpc: "warning",
      "grpc-web": "warning",
      raw: "danger",
      "tls-handshake": "default",
    });
  });

  it("is case-insensitive and tolerates legacy spellings from old rows", () => {
    expect(protocolVariant("WS")).toBe("info");
    expect(protocolVariant("WebSocket")).toBe("info");
    expect(protocolVariant("gRPC-Web")).toBe("warning");
    expect(protocolVariant("TCP")).toBe("danger");
  });

  it("falls back to default for unknown or missing input", () => {
    expect(protocolVariant("unknown")).toBe("default");
    expect(protocolVariant("")).toBe("default");
    expect(protocolVariant(undefined)).toBe("default");
  });
});
